import Vue from 'vue'
import VueRouter from 'vue-router'
import AdmissionPage from '../views/AdmissionPage.vue'
import RecruitmentPage from '../views/RecruitmentPage.vue'
import ContactPage from '../views/ContactPage.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: '/admission'
  },
  {
    path: '/admission',
    name: 'Admission',
    component: AdmissionPage
  },
  {
    path: '/recruitment',
    name: 'Recruitment',
    component: RecruitmentPage
  },
  {
    path: '/registration',
    name: 'Registration',
    component: RecruitmentPage,
    props: { activeTab: 'registration' }
  },
  {
    path: '/contact',
    name: 'Contact',
    component: ContactPage
  }
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
